namespace Refii.Tests.Launcher;

using System.Collections.Generic;
using System.Linq;
using GdUnit4;
using Refii.Core;
using Refii.Launcher.Core;
using static GdUnit4.Assertions;

/// <summary>
/// AN IN-GAME SETTINGS WRITE CHANGES ONLY ITS KEYS (RuntimeConfig.EditText): every other line of the
/// player's file stays as it stands, and a title's file is written from that title's own keyboard table.
/// </summary>
[TestSuite]
public class ConfigEditTests
{
	private const string File =
		"# Runtime config generated by the launcher.\n\n# Controls\n# Pause.\nkey_pause = \"Escape,Tab\"\n" +
		"key_back = \"Escape,Backspace\"\nvibration_strength = 50\n\n# Other\n# Keys this build has no definition for. Preserved verbatim.\n" +
		"key_choice_2 = 2\n";

	private static readonly IReadOnlyDictionary<string, string> NoSet = new Dictionary<string, string>();

	[TestCase]
	public void NothingToChangeLeavesTheFileAsItIs()
	{
		AssertThat(RuntimeConfig.EditText(File, NoSet, new string[0])).IsEqual(File);
	}

	[TestCase]
	public void ASetKeyKeepsItsPlaceAndTheRestStays()
	{
		string after = RuntimeConfig.EditText(File, new Dictionary<string, string> { ["key_back"] = "Escape" }, new string[0]);
		AssertThat(after).IsEqual(File.Replace("key_back = \"Escape,Backspace\"", "key_back = \"Escape\""));
	}

	[TestCase]
	public void ARemovedKeyGoesAndOnlyIt()
	{
		string after = RuntimeConfig.EditText(File, NoSet, new[] { "key_choice_2" });
		AssertThat(after).IsEqual(File.Replace("key_choice_2 = 2\n", string.Empty));
	}

	[TestCase]
	public void ANewKeyGoesInBeforeTheOtherBlock()
	{
		string after = RuntimeConfig.EditText(File, new Dictionary<string, string> { ["zz_new_setting"] = "x" }, new string[0]);
		string[] lines = after.Split('\n');
		int added = System.Array.IndexOf(lines, "zz_new_setting = \"x\"");
		int other = System.Array.IndexOf(lines, "# Other");
		AssertThat(added).IsGreater(0);
		AssertThat(added).IsLess(other);
		AssertThat(after.Replace("zz_new_setting = \"x\"\n", string.Empty)).IsEqual(File);
	}

	[TestCase]
	public void ASetKeyIsHeldOnce()
	{
		string twice = File + "key_back = \"Backspace\"\n";
		string after = RuntimeConfig.EditText(twice, new Dictionary<string, string> { ["key_back"] = "Escape" }, new string[0]);
		AssertThat(after.Split('\n').Count(line => line.StartsWith("key_back", System.StringComparison.Ordinal))).IsEqual(1);
	}

	[TestCase]
	public void ATitlesFileIsWrittenFromItsOwnKeyTable()
	{
		string Default(Engine_Title title, string name) =>
			RuntimeCVarSet.For(title).Single(definition => definition.Name == name).DefaultValue;

		AssertThat(Default(Engine_Title.Fable2, "key_pause")).IsEqual("Escape,Tab");
		AssertThat(Default(Engine_Title.Fable3, "key_pause")).IsEqual("Escape");
		AssertThat(RuntimeCVarSet.For(Engine_Title.Fable3).Any(definition => definition.Name == "key_choice_1")).IsTrue();
		AssertThat(RuntimeCVarSet.For(Engine_Title.Fable2).Any(definition => definition.Name == "key_choice_1")).IsFalse();
	}

	[TestCase]
	public void AnEditOfAnotherTitlesMissingFileWritesThatTitlesTable()
	{
		string dir = System.IO.Path.Combine(Refii.Tests.TestTemp.Root, "refii-edit-title-" + System.Guid.NewGuid().ToString("N"));
		System.IO.Directory.CreateDirectory(dir);
		Engine_Title active = Engine_Title.Active;
		try
		{
			Engine_Title.Active = Engine_Title.Fable3;
			string path = System.IO.Path.Combine(dir, "refii.toml");
			AssertThat(RuntimeConfig.EditValuesForTitle(Engine_Title.Fable2, path,
				new Dictionary<string, string> { ["max_fps"] = "90" }, new string[0], out string error)).IsTrue();
			AssertThat(error).IsEmpty();
			SortedDictionary<string, string> read = RuntimeConfig.ReadValues(path);
			AssertThat(read["max_fps"]).IsEqual("90");
			AssertThat(read.ContainsKey("key_roll")).IsFalse();
		}
		finally
		{
			Engine_Title.Active = active;
			System.IO.Directory.Delete(dir, true);
		}
	}

	[TestCase]
	public void AnEditOfAValueTheFileAlreadyHoldsLeavesTheFileAlone()
	{
		string dir = System.IO.Path.Combine(Refii.Tests.TestTemp.Root, "refii-edit-same-" + System.Guid.NewGuid().ToString("N"));
		System.IO.Directory.CreateDirectory(dir);
		try
		{
			string path = System.IO.Path.Combine(dir, "refii.toml");
			const string text = "max_fps = \"60\"   # mine\nkey_pause = \"Escape,Tab\"\nunknown_key = 7\n";
			System.IO.File.WriteAllText(path, text);
			System.DateTime time = System.IO.File.GetLastWriteTimeUtc(path);
			AssertThat(RuntimeConfig.EditValuesForTitle(Engine_Title.Fable2, path,
				new Dictionary<string, string> { ["max_fps"] = "60", ["key_pause"] = "Escape,Tab", ["unknown_key"] = "7" },
				new[] { "absent_key" }, out string error)).IsTrue();
			AssertThat(error).IsEmpty();
			AssertThat(System.IO.File.ReadAllText(path)).IsEqual(text);
			AssertThat(System.IO.File.GetLastWriteTimeUtc(path)).IsEqual(time);

			// A real change still edits only its line; the unknown key stays as written.
			AssertThat(RuntimeConfig.EditValuesForTitle(Engine_Title.Fable2, path,
				new Dictionary<string, string> { ["max_fps"] = "90", ["unknown_key"] = "7" }, new string[0], out error)).IsTrue();
			AssertThat(System.IO.File.ReadAllText(path)).IsEqual("max_fps = 90\nkey_pause = \"Escape,Tab\"\nunknown_key = 7\n");
		}
		finally
		{
			System.IO.Directory.Delete(dir, true);
		}
	}

	[TestCase]
	public void TheDefaultsPassNamesOnlyWhatItChanged()
	{
		var before = new Dictionary<string, string> { ["a"] = "1", ["b"] = "2", ["gone"] = "x" };
		var after = new Dictionary<string, string> { ["a"] = "1", ["b"] = "3", ["new"] = "4" };
		(Dictionary<string, string> set, List<string> remove) = RuntimeConfig.Changes(before, after);
		AssertThat(set.Keys).ContainsExactlyInAnyOrder("b", "new");
		AssertThat(set["b"]).IsEqual("3");
		AssertThat(remove).ContainsExactly("gone");
	}

	[TestCase]
	public void TheDefaultsPassOnAnExistingFileDropsNoKey()
	{
		// Fable 2's file holding another title's key and a key no build defines: a defaults pass that
		// has something to change (a file from before placed_light_shadows_world) keeps both lines.
		string dir = System.IO.Path.Combine(Refii.Tests.TestTemp.Root, "refii-defaults-" + System.Guid.NewGuid().ToString("N"));
		System.IO.Directory.CreateDirectory(dir);
		try
		{
			string path = System.IO.Path.Combine(dir, "refii.toml");
			System.IO.File.WriteAllText(path,
				"# mine\nplaced_light_shadows = false\nkey_roll = \"Space\"\nsomething_unknown = 7\nkey_pause = \"Escape,Tab\"\n");
			AssertThat(RuntimeConfig.EnsureDefaultsForTitle(Engine_Title.Fable2, path, out string error)).IsTrue();
			AssertThat(error).IsEmpty();
			string text = System.IO.File.ReadAllText(path);
			AssertThat(text).StartsWith("# mine\n");
			AssertThat(text).Contains("key_roll = \"Space\"\n");
			AssertThat(text).Contains("something_unknown = 7\n");
			AssertThat(text).Contains("key_pause = \"Escape,Tab\"\n");
			SortedDictionary<string, string> read = RuntimeConfig.ReadValues(path);
			AssertThat(read["placed_light_shadows"]).IsEqual("true");
			AssertThat(read["placed_light_shadows_world"]).IsEqual("false");
		}
		finally
		{
			System.IO.Directory.Delete(dir, true);
		}
	}
}
